// Training Ground / level generator v2, stage 2 (board 066): MAP EXPANSION x2 / x4 / x6 BY AREA. The canvas grows to the base
// size x sqrt(factor) (x2 ~ 250 x 175, x4 ~ 354 x 248, x6 ~ 434 x 304 m for the 177 x 124 Depot); the old map stays CENTRED, so
// every old object keeps its UE coordinates byte for byte (the one exception: a seam gate, below) and every locked district stays
// where it is. The new area is generated by the same mechanism as a region re-roll (blockTemplates.ts):
//   1. the street plan (seeded by the step's skeleton seed): the old roads that reach the old map's edge are EXTENDED straight to
//      the new edge, a ring street runs round the old map, grid streets every grid_step_m split the margins (all ending at another
//      street or the map edge: no dead ends); the canal is extended along its axis to the new edge with its retaining walls, a
//      bridge wherever a new street crosses it;
//   2. the cells between the streets become LOTS filled from the template catalog (the expansion's block seed), stored in
//      regen.blocks so a later re-roll can give them other types;
//   3. SEAM GATES: an old wall that stands across an extended road within seam_gate_reach_m of the old edge (Depot: the east yard
//      fence across the north street) is opened for the road's width - unless it is locked (then reported);
//   4. the routes are re-checked (evaluate.ts checkLayoutRoutes): a previously completable route must stay so, else the next seed.
// Pure and deterministic: same map + factor + seeds -> the same JSON. Constants: levelgen_v2.json `expansion`.

import type { Vec2 } from '../movement/geometry.ts';
import { pointInPoly, rng } from '../movement/geometry.ts';
import { wallSegments } from '../movement/layout.ts';
import { NavGrid } from '../movement/nav.ts';
import type { BlockRecord as Lot } from './schema.ts';
import { buildTemplate, frameOf, lotSeed, lotsOf, pickTemplates, rectFromUE, rectToUE, streetRectsM, V2 } from './blockTemplates.ts';
import type { RouteReport } from './evaluate.ts';
import { checkLayoutRoutes } from './evaluate.ts';
import type { Rect, Side } from './generate.ts';
import { COVER_SIZE } from './generate.ts';
import { obstacleHeight } from './obstacleHeights.ts';
import type { Profile } from './profile.ts';
import { toUE } from './profile.ts';
import type { CoverKind, GenCover, GenLayout, GenWall, LockDistrict, SpawnPoint } from './schema.ts';
import { CUT_BUILDING_MARGIN_CM, EXPANSION_STATE_VERSION, REGEN_STATE_VERSION, rect, toFormationLayout } from './schema.ts';

const E = V2.expansion;

/** The canvas of an expansion by area: the base size x sqrt(factor), rounded to whole metres. */
export const expansionSize = (base: readonly [number, number], factor: number): [number, number] => [Math.round(base[0] * Math.sqrt(factor)), Math.round(base[1] * Math.sqrt(factor))];

export interface ExpandOptions {
  layout: GenLayout;
  /** 2, 4 or 6 (levelgen_v2.json expansion.factors): the area relative to the BASE map (the generator's size). */
  factor: number;
  /** The seed of the new blocks (templates, street covers). Retries use seed + k * retry_seed_step. */
  seed: number;
  /** The seed of the new street plan (default = seed). A re-roll replays an expansion with its stored skeleton seed. */
  skeletonSeed?: number;
  /** The map's reference profile (its classic blocks, when the map has no stored blocks yet). */
  profile: Profile;
  /** Re-check the routes and retry on a break (default true; the re-roll's replay passes false). */
  gate?: boolean;
  maxRetries?: number;
  checkRoutes?: (l: GenLayout) => RouteReport[];
  /** The old map's blocks (default lotsOf(layout, profile)); the re-roll's replay passes [] (its blocks come from the map). */
  lots?: Lot[];
}

/** An old road / the canal that crosses the seam, and its continuation. */
export interface SeamRoad { id: string; side: Side; kind: 'road' | 'canal'; extension: string }
export interface SeamGate { wall: string; pieces: string[] }
export interface SeamCheck { id: string; side: Side; kind: 'road' | 'canal'; connected: boolean; ratio: number }

export interface ExpandResult {
  ok: boolean;
  layout: GenLayout;
  factor: number;
  size_m: [number, number];
  seed: number;
  retries: number;
  /** New street ids (zones Z_<id>). */
  streets: string[];
  /** New blocks and their types. */
  lots: { id: string; template: string }[];
  roads: SeamRoad[];
  seamGates: SeamGate[];
  /** Seams a locked wall keeps closed (the road ends at the lock). */
  blockedSeams: string[];
  routes: { id: string; mandatory: boolean; completable: boolean; fail?: string }[];
  message: string;
}

type Street = { id: string; r: Rect; dir: 'ns' | 'ew' };

const bboxUE = (pts: readonly Vec2[]): [Vec2, Vec2] => [[Math.min(...pts.map((p) => p[0])), Math.min(...pts.map((p) => p[1]))], [Math.max(...pts.map((p) => p[0])), Math.max(...pts.map((p) => p[1]))]];
const overlaps = (a: Rect, b: Rect) => a[0][0] < b[1][0] && b[0][0] < a[1][0] && a[0][1] < b[1][1] && b[0][1] < a[1][1];
const inside = (r: Rect, p: Vec2) => p[0] > r[0][0] && p[0] < r[1][0] && p[1] > r[0][1] && p[1] < r[1][1];

/** The expanded name: the base name + _x<factor> (an earlier suffix replaced). */
export const expandedName = (name: string, factor: number) => `${name.replace(/_x\d+$/, '')}_x${factor}`;

export function expandLayout(o: ExpandOptions): ExpandResult {
  const old = o.layout;
  const base = old.expansion?.base_size_m ?? old.params.size_m;
  const size = expansionSize(base, o.factor);
  const [w0, h0] = frameOf(old);
  const fail = (message: string): ExpandResult => ({ ok: false, layout: old, factor: o.factor, size_m: size, seed: o.seed, retries: 0, streets: [], lots: [], roads: [], seamGates: [], blockedSeams: [], routes: [], message });
  if (!E.factors.includes(o.factor)) return fail(`множитель ${o.factor}: допустимы ${E.factors.join(', ')}`);
  if (size[0] <= w0 + 1 || size[1] <= h0 + 1) return fail(`карта уже ${w0} x ${h0} м - не меньше x${o.factor} (${size[0]} x ${size[1]} м)`);
  const gate = o.gate ?? true;
  const check = o.checkRoutes ?? checkLayoutRoutes;
  const before = gate ? check(old) : [];
  const was = new Map(before.map((r) => [r.id, r.completable]));
  const maxRetries = Math.max(0, o.maxRetries ?? E.max_retries);
  let last: ExpandResult | null = null;
  for (let k = 0; k <= maxRetries; k++) {
    const seed = o.seed + k * E.retry_seed_step;
    const r = buildExpansion(old, o, size, o.skeletonSeed ?? o.seed, seed);
    r.retries = k;
    if (!gate) return r;
    const after = check(r.layout);
    r.routes = after.map((x) => ({ id: x.id, mandatory: x.mandatory, completable: x.completable, ...(x.fail ? { fail: x.fail } : {}) }));
    const broken = after.filter((x) => was.get(x.id) && !x.completable);
    last = r;
    if (!broken.length) return r;
  }
  return { ...last!, ok: false, layout: old, message: `маршрут ломается во всех ${maxRetries + 1} попытках - карта не изменена` };
}

function buildExpansion(old: GenLayout, o: ExpandOptions, size: [number, number], skel: number, seed: number): ExpandResult {
  const [W, H] = size;
  const base = old.expansion?.base_size_m ?? old.params.size_m;
  const frame: Vec2 = [W, H];
  const [w0, h0] = frameOf(old);
  const ox = (W - w0) / 2, oy = (H - h0) / 2;
  const O: Rect = [[ox, oy], [ox + w0, oy + h0]];
  const SW = E.street_w_m, T = E.cut_wall_t_m, MIN = E.min_block_m, margin = CUT_BUILDING_MARGIN_CM / 100;
  const step = (old.expansion?.steps.length ?? 0) + 1;
  const tag = `x${step}`;
  const M = (r: readonly [Vec2, Vec2]) => rectFromUE(r, frame);
  const U = (p: Vec2) => toUE(p, frame);
  const plan = rng(lotSeed(skel, `${tag}:plan`));
  const jit = () => (plan() * 2 - 1) * E.grid_jitter_m;
  const streets: Street[] = [];
  const addStreet = (dir: 'ns' | 'ew', r: Rect) => { const s = { id: `ST_${tag}_${streets.length + 1}`, r, dir }; streets.push(s); return s; };
  const touch = E.edge_touch_m;
  // ---- 1. the street plan --------------------------------------------------------------------------------------------------
  const roads: SeamRoad[] = [];
  const oldStreets = old.zones.filter((z) => z.id.startsWith('Z_ST_')).map((z) => ({ id: z.id, ue: bboxUE(z.poly), r: M(bboxUE(z.poly)) }));
  for (const s of oldStreets) {
    const [[x0, y0], [x1, y1]] = s.r;
    const horiz = x1 - x0 >= y1 - y0;
    if (horiz && x0 <= O[0][0] + touch) roads.push({ id: s.id, side: 'west', kind: 'road', extension: addStreet('ew', [[0, y0], [O[0][0], y1]]).id });
    if (horiz && x1 >= O[1][0] - touch) roads.push({ id: s.id, side: 'east', kind: 'road', extension: addStreet('ew', [[O[1][0], y0], [W, y1]]).id });
    if (!horiz && y0 <= O[0][1] + touch) roads.push({ id: s.id, side: 'north', kind: 'road', extension: addStreet('ns', [[x0, 0], [x1, O[0][1]]]).id });
    if (!horiz && y1 >= O[1][1] - touch) roads.push({ id: s.id, side: 'south', kind: 'road', extension: addStreet('ns', [[x0, O[1][1]], [x1, H]]).id });
  }
  // the canal, extended along its axis (its trench band; + the retaining walls and the building margin = no lot there)
  const cutM = old.cut ? M(bboxUE(old.cut.poly)) : null;
  const canal: { r: Rect; side: Side }[] = [];
  if (cutM) {
    const horiz = cutM[1][0] - cutM[0][0] >= cutM[1][1] - cutM[0][1];
    if (horiz && cutM[0][0] <= O[0][0] + touch) canal.push({ r: [[0, cutM[0][1]], [O[0][0], cutM[1][1]]], side: 'west' });
    if (horiz && cutM[1][0] >= O[1][0] - touch) canal.push({ r: [[O[1][0], cutM[0][1]], [W, cutM[1][1]]], side: 'east' });
    if (!horiz && cutM[0][1] <= O[0][1] + touch) canal.push({ r: [[cutM[0][0], 0], [cutM[1][0], O[0][1]]], side: 'north' });
    if (!horiz && cutM[1][1] >= O[1][1] - touch) canal.push({ r: [[cutM[0][0], O[1][1]], [cutM[1][0], H]], side: 'south' });
  }
  const canalHoriz = (c: { side: Side }) => c.side === 'west' || c.side === 'east';
  const canalBand = (c: { r: Rect; side: Side }): Rect => canalHoriz(c) ? [[c.r[0][0], c.r[0][1] - T - margin], [c.r[1][0], c.r[1][1] + T + margin]] : [[c.r[0][0] - T - margin, c.r[0][1]], [c.r[1][0] + T + margin, c.r[1][1]]];
  const bands = canal.map(canalBand);
  // the ring round the old map + the outer grid lines (both span the whole canvas)
  const gap = SW + MIN + 2;
  const xLines: number[] = [], yLines: number[] = [];
  const ring = { w: ox >= gap, e: W - O[1][0] >= gap, n: oy >= gap, s: H - O[1][1] >= gap };
  if (ring.w) xLines.push(O[0][0] - SW / 2);
  if (ring.e) xLines.push(O[1][0] + SW / 2);
  if (ring.n) yLines.push(O[0][1] - SW / 2);
  if (ring.s) yLines.push(O[1][1] + SW / 2);
  const outward = (start: number, dir: -1 | 1, limit: number, out: number[]) => {
    let prev = start;
    for (;;) {
      const c = prev + dir * E.grid_step_m + jit();
      const roomToEdge = dir < 0 ? c - SW / 2 : limit - (c + SW / 2);
      if (roomToEdge < MIN + 2 || Math.abs(c - prev) - SW < MIN + 2) break;
      out.push(c); prev = c;
    }
  };
  if (ring.w) outward(O[0][0] - SW / 2, -1, 0, xLines);
  if (ring.e) outward(O[1][0] + SW / 2, 1, W, xLines);
  if (ring.n) outward(O[0][1] - SW / 2, -1, 0, yLines);
  if (ring.s) outward(O[1][1] + SW / 2, 1, H, yLines);
  for (const x of xLines) addStreet('ns', [[x - SW / 2, 0], [x + SW / 2, H]]);
  for (const y of yLines) addStreet('ew', [[0, y - SW / 2], [W, y + SW / 2]]);
  // local streets: N / S bands above / below the old map (N-S, from the map edge to the ring), W / E bands beside it (E-W)
  const local = (lo: number, hi: number, exist: number[], keepOut: [number, number][]) => {
    const n = Math.max(0, Math.round((hi - lo) / E.grid_step_m) - 1);
    const out: number[] = [];
    for (let i = 1; i <= n; i++) {
      const c = lo + ((hi - lo) * i) / (n + 1) + jit();
      if (c - SW / 2 - lo < MIN + 2 || hi - (c + SW / 2) < MIN + 2) continue;
      if ([...exist, ...out].some((e) => Math.abs(e - c) < gap)) continue;
      if (keepOut.some(([a, b]) => c + SW / 2 + MIN > a && c - SW / 2 - MIN < b)) continue;
      out.push(c);
    }
    return out;
  };
  const nEdge = ring.n ? O[0][1] - SW : O[0][1], sEdge = ring.s ? O[1][1] + SW : O[1][1];
  const wEdge = ring.w ? O[0][0] - SW : O[0][0], eEdge = ring.e ? O[1][0] + SW : O[1][0];
  // (only with a ring street to end at: a local street never dead-ends against the old map)
  if (ring.n && nEdge >= MIN + 2) for (const x of local(O[0][0], O[1][0], [], [])) addStreet('ns', [[x - SW / 2, 0], [x + SW / 2, nEdge]]);
  if (ring.s && H - sEdge >= MIN + 2) for (const x of local(O[0][0], O[1][0], [], [])) addStreet('ns', [[x - SW / 2, sEdge], [x + SW / 2, H]]);
  const ewIn = (x0: number, x1: number) => streets.filter((s) => s.dir === 'ew' && s.r[0][0] < x1 && s.r[1][0] > x0).map((s) => (s.r[0][1] + s.r[1][1]) / 2);
  const bandY = (x0: number, x1: number): [number, number][] => bands.filter((b) => b[0][0] < x1 && b[1][0] > x0).map((b) => [b[0][1], b[1][1]]);
  if (ring.w && wEdge >= MIN + 2) for (const y of local(O[0][1], O[1][1], ewIn(0, wEdge), bandY(0, wEdge))) addStreet('ew', [[0, y - SW / 2], [wEdge, y + SW / 2]]);
  if (ring.e && W - eEdge >= MIN + 2) for (const y of local(O[0][1], O[1][1], ewIn(eEdge, W), bandY(eEdge, W))) addStreet('ew', [[eEdge, y - SW / 2], [W, y + SW / 2]]);

  // ---- 2. the canal: polygon, retaining walls split round the bridges, zones ----------------------------------------------
  const walls: GenWall[] = [];
  const crossings: NonNullable<GenLayout['cut']>['crossings'] = [];
  let cut = old.cut;
  const zonesNew: GenLayout['zones'] = [];
  if (old.cut && cutM && canal.length) {
    const ext = canal.reduce<Rect>((acc, c) => [[Math.min(acc[0][0], c.r[0][0]), Math.min(acc[0][1], c.r[0][1])], [Math.max(acc[1][0], c.r[1][0]), Math.max(acc[1][1], c.r[1][1])]], cutM);
    const cw = E.crossing_w_m;
    let xi = 0, wi = 0;
    canal.forEach((c, ci) => {
      const horiz = canalHoriz(c);
      const across = streets.filter((s) => (horiz ? s.dir === 'ns' : s.dir === 'ew') && (horiz ? s.r[0][0] < c.r[1][0] && s.r[1][0] > c.r[0][0] && s.r[0][1] <= c.r[0][1] && s.r[1][1] >= c.r[1][1] : s.r[0][1] < c.r[1][1] && s.r[1][1] > c.r[0][1] && s.r[0][0] <= c.r[0][0] && s.r[1][0] >= c.r[1][0]));
      const gaps: [number, number][] = [];
      for (const s of across) {
        const m = horiz ? (s.r[0][0] + s.r[1][0]) / 2 : (s.r[0][1] + s.r[1][1]) / 2;
        gaps.push([m - cw / 2, m + cw / 2]);
        const poly: Rect = horiz ? [[m - cw / 2, c.r[0][1] - T], [m + cw / 2, c.r[1][1] + T]] : [[c.r[0][0] - T, m - cw / 2], [c.r[1][0] + T, m + cw / 2]];
        crossings.push({ id: `X_${tag}_${++xi}`, poly: rect.poly(poly).map(U), kind: 'bridge' });
      }
      const lo = horiz ? c.r[0][0] : c.r[0][1], hi = horiz ? c.r[1][0] : c.r[1][1];
      const pieces = (g: [number, number][]) => {
        const out: [number, number][] = []; let cur = lo;
        for (const [a, b] of [...g].sort((p, q) => p[0] - q[0])) { if (a - cur >= 0.3) out.push([cur, Math.min(a, hi)]); cur = Math.max(cur, b); }
        if (hi - cur >= 0.3) out.push([cur, hi]);
        return out;
      };
      for (const [sideTag, line] of (horiz ? [['N', c.r[0][1] - T / 2], ['S', c.r[1][1] + T / 2]] : [['W', c.r[0][0] - T / 2], ['E', c.r[1][0] + T / 2]]) as [string, number][]) {
        for (const [a, b] of pieces(gaps)) {
          const pa: Vec2 = horiz ? [a, line] : [line, a], pb: Vec2 = horiz ? [b, line] : [line, b];
          walls.push({ id: `CUTWALL_${sideTag}_${tag}_${++wi}`, a: U(pa), b: U(pb), height: obstacleHeight('high_mantle'), thickness: T * 100, kind: 'cut_wall' });
        }
      }
      const zid = `Z_cut_${tag}_${ci + 1}`;
      zonesNew.push({ id: zid, kind: 'corridor', set_piece: 'cut_crossing', poly: rect.poly(c.r).map(U), intent: 'kill_zone' });
      roads.push({ id: 'Z_cut', side: c.side, kind: 'canal', extension: zid });
    });
    cut = { ...old.cut, poly: rect.poly(ext).map(U), crossings: [...old.cut.crossings, ...crossings] };
  }
  for (const s of streets) zonesNew.push({ id: `Z_${s.id}`, kind: 'wall_run', set_piece: 'street', poly: rect.poly(s.r).map(U) });

  // ---- 3. the blocks: the cells between the streets in each margin band -----------------------------------------------------
  const regions: Rect[] = [[[0, 0], [W, O[0][1]]], [[0, O[1][1]], [W, H]], [[0, O[0][1]], [O[0][0], O[1][1]]], [[O[1][0], O[0][1]], [W, O[1][1]]]];
  const cells: Rect[] = [];
  for (const R of regions) {
    if (R[1][0] - R[0][0] < MIN + 2 || R[1][1] - R[0][1] < MIN + 2) continue;
    const xs = new Set([R[0][0], R[1][0]]), ys = new Set([R[0][1], R[1][1]]);
    for (const s of streets) {
      if (!overlaps(s.r, R)) continue;
      if (s.dir === 'ns') { xs.add(Math.max(R[0][0], s.r[0][0])); xs.add(Math.min(R[1][0], s.r[1][0])); } else { ys.add(Math.max(R[0][1], s.r[0][1])); ys.add(Math.min(R[1][1], s.r[1][1])); }
    }
    for (const b of bands) if (overlaps(b, R)) { ys.add(Math.max(R[0][1], b[0][1])); ys.add(Math.min(R[1][1], b[1][1])); xs.add(Math.max(R[0][0], b[0][0])); xs.add(Math.min(R[1][0], b[1][0])); }
    const X = [...xs].sort((a, b) => a - b), Y = [...ys].sort((a, b) => a - b);
    for (let j = 0; j + 1 < Y.length; j++) for (let i = 0; i + 1 < X.length; i++) {
      const c: Rect = [[X[i], Y[j]], [X[i + 1], Y[j + 1]]];
      if (c[1][0] - c[0][0] < MIN + 2 || c[1][1] - c[0][1] < MIN + 2) continue;
      const mid: Vec2 = [(c[0][0] + c[1][0]) / 2, (c[0][1] + c[1][1]) / 2];
      if (streets.some((s) => inside(s.r, mid)) || bands.some((b) => inside(b, mid))) continue;
      cells.push([[c[0][0] + 1, c[0][1] + 1], [c[1][0] - 1, c[1][1] - 1]]);
    }
  }
  const newLots: Lot[] = cells.map((c, i) => ({ id: `LOT_${tag}_${i + 1}`, rect: rectToUE(c, frame), template: '' }));
  const ctx = { seed, frame, streets_m: [...streetRectsM(old).map((r) => M(rectToUE(r, frameOf(old)))), ...streets.map((s) => s.r)], verticality: old.params.verticality, density: old.params.density };
  const content = { walls: [] as GenWall[], buildings: [] as GenLayout['buildings'], ladders: [] as GenLayout['ladders'], covers: [] as GenCover[], zones: [] as GenLayout['zones'], ambush_points: [] as GenLayout['ambush_points'], mantle_edges: [] as NonNullable<GenLayout['mantle_edges']> };
  for (const lot of newLots) {
    const t = pickTemplates(lot, '', seed, frame)[0];
    if (!t) { lot.template = 'empty'; continue; }
    const b = buildTemplate(t, lot, ctx);
    lot.template = t;
    for (const k of Object.keys(content) as (keyof typeof content)[]) (content[k] as object[]).push(...(b.content[k] as object[]));
  }
  // street covers (the classic street zones' barriers, at the expansion's lighter density)
  const coverRnd = rng(lotSeed(seed, `${tag}:covers`));
  const kinds: CoverKind[] = ['jersey', 'sandbag', 'wreck', 'barrel'];
  let cn = 0;
  for (const s of streets) {
    const want = Math.round(((s.r[1][0] - s.r[0][0]) * (s.r[1][1] - s.r[0][1]) / 100) * E.street_cover_density * old.params.density);
    for (let t = 0, placed = 0; placed < want && t < want * 20; t++) {
      const p: Vec2 = [s.r[0][0] + 1.5 + coverRnd() * (s.r[1][0] - s.r[0][0] - 3), s.r[0][1] + 1.5 + coverRnd() * (s.r[1][1] - s.r[0][1] - 3)];
      if (bands.some((b) => inside(b, p)) || inside(O, p)) continue;
      const kind = kinds[Math.floor(coverRnd() * kinds.length)];
      const pos = U(p);
      if (content.covers.some((c) => Math.hypot(c.pos[0] - pos[0], c.pos[1] - pos[1]) < 500)) continue;
      content.covers.push({ id: `COV_${tag}_st${++cn}`, pos, yaw: (s.dir === 'ew' ? 90 : 0) + Math.round(coverRnd()) * 180, size: COVER_SIZE[kind], kind });
      placed++;
    }
  }

  // ---- 4. seam gates: open an old wall across an extended road at the old edge -----------------------------------------------
  const locks: LockDistrict[] = old.regen?.locks ?? [];
  const seamGates: SeamGate[] = [];
  const blockedSeams: string[] = [];
  const oldWalls = old.walls.slice();
  const reach = E.seam_gate_reach_m * 100;
  const edgeUE: Record<Side, { axis: 0 | 1; at: number }> = { west: { axis: 1, at: old.bounds.min[1] }, east: { axis: 1, at: old.bounds.max[1] }, north: { axis: 0, at: old.bounds.max[0] }, south: { axis: 0, at: old.bounds.min[0] } };
  for (const road of roads) {
    if (road.kind !== 'road') continue;
    const s = oldStreets.find((x) => x.id === road.id)!;
    const e = edgeUE[road.side];
    const along = e.axis === 1 ? 0 : 1; // the coordinate along the edge
    const span: [number, number] = [s.ue[0][along], s.ue[1][along]];
    for (let i = 0; i < oldWalls.length; i++) {
      const w = oldWalls[i];
      if ((w.floor ?? 0) !== 0 || w.kind === 'cut_wall') continue;
      if (Math.abs(w.a[e.axis] - e.at) > reach || Math.abs(w.b[e.axis] - e.at) > reach || Math.abs(w.a[e.axis] - w.b[e.axis]) > 1) continue;
      const lo = Math.min(w.a[along], w.b[along]), hi = Math.max(w.a[along], w.b[along]);
      if (hi <= span[0] + 50 || lo >= span[1] - 50) continue;
      const mid: Vec2 = [(w.a[0] + w.b[0]) / 2, (w.a[1] + w.b[1]) / 2];
      if (locks.some((k) => pointInPoly(mid, k.poly) || pointInPoly(w.a, k.poly) || pointInPoly(w.b, k.poly))) { blockedSeams.push(`${road.id}:${w.id}`); continue; }
      const at = (v: number): Vec2 => { const p: Vec2 = [w.a[0], w.a[1]]; p[along] = v; return p; };
      const parts: [number, number][] = [];
      if (span[0] - lo >= 30) parts.push([lo, span[0]]);
      if (hi - span[1] >= 30) parts.push([span[1], hi]);
      const famM = /^(.*_[NSEW]_)(\d+)$/.exec(w.id);
      const nextId = (k: number) => {
        if (k === 0) return w.id;
        if (famM) { let n = Math.max(...oldWalls.map((x) => (x.id.startsWith(famM[1]) ? Number(x.id.slice(famM[1].length)) || 0 : 0))) + 1; while (oldWalls.some((x) => x.id === `${famM[1]}${n}`)) n++; return `${famM[1]}${n}`; }
        return `${w.id}_g${k}`;
      };
      const repl: GenWall[] = parts.map(([a, b], k) => ({ ...w, id: nextId(k), a: at(a), b: at(b) }));
      oldWalls.splice(i, 1, ...repl);
      i += repl.length - 1;
      seamGates.push({ wall: w.id, pieces: repl.map((x) => x.id) });
    }
  }

  // ---- 5. edge spawns + the layout ------------------------------------------------------------------------------------------
  const spawns: SpawnPoint[] = [];
  const inset = E.spawn_inset_m;
  for (const s of streets) {
    const c: Vec2 = [(s.r[0][0] + s.r[1][0]) / 2, (s.r[0][1] + s.r[1][1]) / 2];
    const ends: Vec2[] = s.dir === 'ew' ? [[s.r[0][0] + inset, c[1]], [s.r[1][0] - inset, c[1]]] : [[c[0], s.r[0][1] + inset], [c[0], s.r[1][1] - inset]];
    for (const p of ends) {
      const atEdge = p[0] <= inset + 0.5 || p[0] >= W - inset - 0.5 || p[1] <= inset + 0.5 || p[1] >= H - inset - 0.5;
      if (atEdge && !bands.some((b) => inside(b, p))) spawns.push({ id: `SPAWN_${tag}_${spawns.length + 1}`, pos: U(p), kind: 'edge' });
    }
  }
  const oldLots = o.lots ?? lotsOf(old, o.profile);
  const state = old.regen ? { ...old.regen } : { version: REGEN_STATE_VERSION, locks: [], rerolls: [] };
  const layout: GenLayout = {
    ...old,
    name: expandedName(old.name, o.factor),
    bounds: { min: [-(H / 2) * 100, -(W / 2) * 100], max: [(H / 2) * 100, (W / 2) * 100] },
    walls: [...oldWalls, ...walls, ...content.walls],
    buildings: [...old.buildings, ...content.buildings],
    ...(cut ? { cut } : {}),
    ladders: [...old.ladders, ...content.ladders],
    covers: [...old.covers, ...content.covers],
    zones: [...old.zones, ...zonesNew, ...content.zones],
    spawn_points: [...old.spawn_points, ...spawns],
    ambush_points: [...old.ambush_points, ...content.ambush_points],
    ...(old.mantle_edges || content.mantle_edges.length ? { mantle_edges: [...(old.mantle_edges ?? []), ...content.mantle_edges] } : {}),
    regen: { ...state, version: REGEN_STATE_VERSION, blocks: [...oldLots, ...newLots] },
    expansion: { version: EXPANSION_STATE_VERSION, base_size_m: [base[0], base[1]], steps: [...(old.expansion?.steps ?? []), { factor: o.factor, seed: skel, size_m: [W, H] }],
      seams: [...(old.expansion?.seams ?? []), [[old.bounds.min[0], old.bounds.min[1]], [old.bounds.max[0], old.bounds.max[1]]]] },
  };
  const counts = new Map<string, number>();
  for (const k of newLots) counts.set(k.template, (counts.get(k.template) ?? 0) + 1);
  return {
    ok: true, layout, factor: o.factor, size_m: [W, H], seed, retries: 0, streets: streets.map((s) => s.id), lots: newLots.map((k) => ({ id: k.id, template: k.template })), roads, seamGates, blockedSeams, routes: [],
    message: `расширено x${o.factor}: ${W} x ${H} м, улиц ${streets.length}, кварталов ${newLots.length} (${[...counts].map(([t, n]) => `${t} ${n}`).join(', ')}), продолжено дорог ${roads.filter((r) => r.kind === 'road').length}, канал ${canal.length ? 'продолжен' : 'нет'}, проёмов на шве ${seamGates.length}${blockedSeams.length ? `, закрыто замком ${blockedSeams.length}` : ''}`,
  };
}

/**
 * The seam check: each old road / canal end that crosses the old edge is walked (ground / cut layer nav) from 5 m inside the old map
 * to 3 m before the new edge along its extension; connected + path length / straight distance (a dead end shows as unconnected or a
 * long detour).
 */
export function checkSeams(l: GenLayout, roads: readonly SeamRoad[]): SeamCheck[] {
  if (!l.expansion?.seams.length) return [];
  const frame = frameOf(l);
  const O = rectFromUE(l.expansion.seams[l.expansion.seams.length - 1], frame);
  const grids = new Map<string, NavGrid>();
  const grid = (layer: string) => { let g = grids.get(layer); if (!g) { const f = toFormationLayout(l, layer); g = new NavGrid(wallSegments(f), f.bounds.min, f.bounds.max); grids.set(layer, g); } return g; };
  const out: SeamCheck[] = [];
  for (const r of roads) {
    const z = l.zones.find((x) => x.id === (r.kind === 'canal' ? r.extension : `Z_${r.extension}`));
    if (!z) { out.push({ id: r.id, side: r.side, kind: r.kind, connected: false, ratio: Infinity }); continue; }
    const ext = rectFromUE(bboxUE(z.poly), frame);
    const mid = r.side === 'west' || r.side === 'east' ? (ext[0][1] + ext[1][1]) / 2 : (ext[0][0] + ext[1][0]) / 2;
    const a: Vec2 = r.side === 'west' ? [O[0][0] + 5, mid] : r.side === 'east' ? [O[1][0] - 5, mid] : r.side === 'north' ? [mid, O[0][1] + 5] : [mid, O[1][1] - 5];
    const b: Vec2 = r.side === 'west' ? [3, mid] : r.side === 'east' ? [frame[0] - 3, mid] : r.side === 'north' ? [mid, 3] : [mid, frame[1] - 3];
    const g = grid(r.kind === 'canal' ? 'cut' : 'ground');
    const A = toUE(a, frame), B = toUE(b, frame);
    const p = g.walkable(A) && g.walkable(B) ? g.path(A, B) : null;
    const len = p ? p.slice(1).reduce((s, q, i) => s + Math.hypot(q[0] - p[i][0], q[1] - p[i][1]), 0) : Infinity;
    out.push({ id: r.id, side: r.side, kind: r.kind, connected: !!p, ratio: p ? Math.round((len / Math.hypot(B[0] - A[0], B[1] - A[1])) * 100) / 100 : Infinity });
  }
  return out;
}
